from lib import *
S = SS('g55')
steps = [
    step("单个 goroutine 空转 5 秒,每轮调用 workA 6 个单位、workB 3 个、workC 1 个(单位是固定的迭代数)。程序自己用 time.Now 量到的真实占比:A 60.1% / B 30.0% / C 10.0%。CPU profile(go tool pprof -top)给出:Duration 5.20s,Total samples = 4770ms(91.82%);flat 占比 workA 58.07%、workB 29.98%、workC 9.85%,另有 runtime.asyncPreempt 2.10%。", t=tl(S(1)), done=lidx(S(1), 'main.workA', 'main.workB', 'main.workC'), mark=lidx(S(1), 'Total samples', 'asyncPreempt', '真实占比'), b=bars([['workA 真实 60.1% → profile', 58.1, '58.1%'], ['workB 真实 30.0% → profile', 30.0, '30.0%'], ['workC 真实 10.0% → profile', 9.9, '9.9%']], 60, done=[0, 1, 2]), kv=KV([['真实占比 A/B/C', '60.1 / 30.0 / 10.0'], ['profile 的 flat%', '58.07 / 29.98 / 9.85'], ['Total samples', '4770 ms,占墙钟 91.82%']], ['Total samples'])),
    step("4 个 goroutine 同时空转 2 秒(GOMAXPROCS=4):Duration 2.20s,Total samples = 6090ms(276.62%)——采样总量超过墙钟时间,因为 CPU profile 统计的是所有线程的 CPU 时间。按 4×2.2 s 算应有约 8.8 秒,实际只有 6.09 秒,为什么只有约 69%,我没有查。flat 占比 workA 55.17%、workB 26.77%、workC 9.03%、asyncPreempt 8.70%。", t=tl(S(2)), done=lidx(S(2), 'main.workA', 'main.workB', 'main.workC'), mark=lidx(S(2), 'Total samples', 'asyncPreempt'), b=bars([['理论上限 4×2.2s (ms)', 8800, '8800'], ['实际 Total samples (ms)', 6090, '6090'], ['单 goroutine 同长度 (ms)', 2200, '2200']], 8800, done=[1], mark=[0]), kv=KV([['Total samples', '6090 ms,276.62% 的墙钟时间'], ['理论值', '4 个线程×2.2 s ≈ 8800 ms'], ['未查', '为什么只有约 69%']], ['未查'])),
    step("每轮 workA 之后 time.Sleep(4ms),跑 3 秒:Duration 3.14s,Total samples = 1390ms(44.33%)。睡着的时间确实没算进去,但调用 Sleep 的路径出现了:runtime.kevent flat 910ms(65.47%),调用链是 runtime.(*timer).reset → modify → maybeAdd;main.workA 只占 flat 23.02%(cum 30.94%)。为什么在 kevent 上花了这么多 CPU 时间,我没有深查。", t=tl(S(3)), done=lidx(S(3), 'main.workA', 'Total samples'), mark=lidx(S(3), 'runtime.kevent', 'timer).reset', 'timer).modify', 'timer).maybeAdd'), b=bars([['runtime.kevent flat(ms)', 910, '910'], ['main.workA flat', 320, '320'], ['asyncPreempt', 110, '110']], 910, mark=[0], done=[1]), kv=KV([['Total samples', '1390 ms(墙钟 3.14 s 的 44.33%)'], ['kevent', '910 ms,65.47%'], ['workA', '320 ms,23.02%'], ['含义', 'profile 里只有 CPU 时间,不含睡眠;但睡眠路径上的系统调用有成本']], ['含义'])),
    step("采样窗口越短,估计越不准。C 的真实占比约 10%,每种窗口各跑 6 次:100 ms 窗口估计占比最小 0.0% / 中位 10.0% / 最大 10.0%;300 ms:6.7% / 11.8% / 13.8%;1000 ms:8.5% / 10.3% / 13.7%;4000 ms:9.5% / 10.3% / 11.2%。窗口 4 秒时 6 次都落在 9.5%–11.2%。", t=tl(S(4)), done=lidx(S(4), '4000 ms:', '1000 ms:'), mark=lidx(S(4), '100 ms:', '300 ms:'), b=bars([['100 ms 窗口:最大−最小(百分点)', 10.0, '10.0'], ['300 ms', 7.1, '7.1'], ['1000 ms', 5.2, '5.2'], ['4000 ms', 1.7, '1.7']], 10, mark=[0, 1], done=[2, 3]), kv=KV([['100 ms', '估计 0.0%–10.0%'], ['4000 ms', '估计 9.5%–11.2%'], ['结论', '窗口越长,波动越小']], ['结论'])),
    step("源码为什么是 100 Hz(runtime/pprof/pprof.go 的注释):运行时例程允许可变的采样率,但操作系统实际上不能以高于约 500 Hz 的频率触发信号,处理信号也不便宜(主要是取栈);100 Hz 是合理的选择——足够频繁以产生有用数据,又不会拖垮系统,还是个整数,便于把样本数换算成秒;所以硬编码为 const hz = 100。", t=tl(S(5)), done=lidx(S(5), '500 Hz', 'not cheap'), mark=lidx(S(5), '100 Hz is a reasonable choice', 'const hz = 100'), kv=KV([['采样率', '硬编码 100 Hz'], ['上限原因', '系统最多约 500 Hz,取栈不便宜'], ['换算', '1 个样本 = 10 ms']], ['采样率'])),
]
A = mkartg('g55', 55, 'Go,pprof,CPU profile,采样,火焰图,真实验证,动画演示',
    '在 Go 1.27.1(arm64 macOS)里实测 CPU profile:真实占比 60.1/30.0/10.0 的三个函数,profile 给出 58.07/29.98/9.85;4 个 goroutine 并行时 Total samples 是墙钟的 276.62%;Sleep 的睡眠时间不在 profile 里,但 Sleep 路径上的 kevent 占了 65.47%;窗口 100 ms 时 10% 的函数估计在 0.0%–10.0% 间摆动,4 秒时只在 9.5%–11.2% 间;并读了 100 Hz 采样率的源码注释。',
    'CPU profile 靠定时信号采样,只能告诉你 CPU 时间花在哪。这篇用已知占比的三个函数检验它的准确度,看多 goroutine 时样本总量怎么算,验证睡眠不算 CPU 时间,并量采样窗口多短会让结果不可信。',
    [('58.07 / 29.98 / 9.85', '真实占比 60.1 / 30.0 / 10.0 的三个函数,profile 给出的 flat%'), ('276.62%', '4 个 goroutine 并行 2 秒,Total samples 相对墙钟时间的比例'), ('0.0%–10.0%', '100 ms 窗口里真实占 10% 的函数的估计范围(6 次)')],
    [('采样结果和真实值接近', '<p>三个函数的真实 CPU 占比是 60.1%、30.0%、10.0%(程序自己用 <code>time.Now</code> 量),5 秒的 profile 给出 58.07%、29.98%、9.85%,另有约 2% 落在 <code>runtime.asyncPreempt</code>(抢占信号打断时的栈)。Total samples 是墙钟时间的 91.82%,即约 91 个样本每秒,而不是 100。</p>'),
     ('多个 goroutine', '<p>CPU profile 统计所有线程的 CPU 时间,所以 4 个 goroutine 并行 2.2 秒得到 276.62% 的 Total samples。我预期接近 400%,实际只有约 69%,原因没查(可能与 macOS 上信号计时的特性有关,没有验证)。</p>'),
     ('睡眠不算,但路径要钱', '<p>每轮 <code>Sleep(4ms)</code> 的程序,Total samples 只有墙钟的 44.33%:睡着的时间没有样本。但 <code>time.Sleep</code> 的调用路径里有 <code>runtime.kevent</code>,占了 65.47% 的 flat。所以在 macOS 上看到 kevent 很高,不一定是网络,可能只是定时器在重置。我没有深究这一段 CPU 时间为什么这么大。</p>'),
     ('窗口多长才够', '<p>真实占 10% 的函数,100 ms 的窗口(约 10 个样本)6 次估计在 0.0% 到 10.0%;300 ms 在 6.7% 到 13.8%;4 秒的窗口 6 次都在 9.5% 到 11.2%。所以对占比小的函数,太短的 profile 不能作为结论。</p>'),
     ('为什么是 100 Hz', '<p>源码注释:系统最多约 500 Hz,取栈开销不小,100 Hz 足够有用又不拖垮系统,并且一个样本正好是 10 ms,换算方便。这是硬编码的,不是配置项。</p>')],
    steps,
    [ENV_G + '。被测程序的三个函数是同一段整数迭代(noinline),每轮 6:3:1 单位;真实占比用 time.Now 在每次调用前后量;profile 用 go tool pprof -top 读取,占比用前 10 个节点中 workA/B/C 的 flat 重新归一;第四节每种窗口各运行 6 次(进程重启);读过的源码:runtime/pprof/pprof.go 的 StartCPUProfile 注释',
     '没有验证:火焰图的绘制(本文没有生成图)、Linux 上的 setitimer/timer_create 差异、多 goroutine 时样本总量偏低的原因、kevent 占比高的原因、内联函数在 profile 里的表现、pprof 的 -sample_index 其它选项'],
    'CPU profile')
